import re
from moler.exceptions import CommandFailure
from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand

__author__ = 'Dawid Przybylo'
__copyright__ = 'Copyright (C) 2020, Nokia'
__email__ = 'dawid.przybylo@nokia.com'


class RtpmParse(GenericEMSSIMCommand):
    """RtpmParse command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None, mfilter=None, cfilter=None, short=None, quiet=None):
        """
        Rtpmdeactivate command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        :param mfilter: To filter group of counters example: -mfilter M8051,M8011
        :param cfilter: To filter specific counters example: -cfilter M8051C26,M8051C23
        :param short: forces using abbreviated counters name instead of full name in parsed output
        :param quiet: quiet mode - do not print parsed data, only write to RTPM_Data.pl file
        """
        super(RtpmParse, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.ret_required = True
        self.mfilter = mfilter
        self.cfilter = cfilter
        self.short = short
        self.quiet = quiet

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = 'rtpm_parse'

        if self.mfilter:
            cmd = f"{cmd} -mfilter {self.mfilter}"
        elif self.cfilter:
            cmd = f"{cmd} -cfilter {self.cfilter}"
        if self.short:
            cmd = f"{cmd} -short"
        if self.quiet:
            cmd = f"{cmd} -q"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._parse_disconnect(line)
                self._parse_rtpm_data_file(line)
            except ParsingDone:
                pass
        return super(RtpmParse, self).on_new_line(line, is_full_line)

    # 17:12:23          |ERROR: No RTPM files collected
    _re_error = re.compile(r"ERROR:\s(?P<ERROR_MSG>.*)")

    def _parse_error(self, line):
        if self._regex_helper.search_compiled(RtpmParse._re_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR_MSG')}"))
            raise ParsingDone

    # 17:12:32          |WARNING: eNodeB disconnected BTSOM link
    _re_disconnect = re.compile(r"eNodeB disconnected BTSOM link")

    def _parse_disconnect(self, line):
        if self._regex_helper.search_compiled(RtpmParse._re_disconnect, line):
            self.set_exception(CommandFailure(self, "ENB was disconnected during parsing"))
            raise ParsingDone

    # 13:40:30          |RTPM data stored to file: /home/flexi1/UPLOADS/KEYSTATS/RTPM/RTPM_Data.pl
    _re_rtpm_data_file = re.compile(r'RTPM data stored to file:\s*(?P<RTPM_DATA_FILE>\S+)')

    def _parse_rtpm_data_file(self, line):
        if self._regex_helper.search_compiled(RtpmParse._re_rtpm_data_file, line):
            self.current_ret["RTPM_DATA_FILE"] = self._regex_helper.group("RTPM_DATA_FILE")
            raise ParsingDone


